window.HOEREN_TESTS[52] = {"id":"familienfeier-und-hochzeit","name":"Familienfeier und Hochzeit","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Lisa, hier ist Anna. Hör mal, meine Schwester heiratet im Juli! Große Feier, 80 Gäste. Du bist herzlich eingeladen. Standesamt um 11 Uhr, Restaurant um 14 Uhr, Tanzen abends. Ein Geschenk ist nicht nötig, und eine Karte auch nicht. Bring bitte einen Partner mit, wir haben keinen Single-Tisch. Ruf zurück, ich freue mich!","gender":"f","q":"Was sollte Lisa mitbringen?","opts":["Ein Geschenk.","Einen Partner.","Eine Karte."],"correct":1},{"transcript":"Liebe Familie: Mama hat Geburtstag am Sonntag und wird 70. Wir machen eine Überraschungsparty im Restaurant Sonnenblume. Mama weiß nicht alles, sie denkt, es ist nur ein normales Essen. Bitte nichts sagen! Treffen 12 Uhr 30, sie kommt um 13 Uhr. Alle Geschwister sind da, sogar Onkel aus Kanada. Seid pünktlich!","gender":"m","q":"Was ist besonderes?","opts":["Normales Essen.","Mama weiß alles.","Es ist eine Überraschung."],"correct":2},{"transcript":"Achtung Familie: Die Konfirmation von Klein-Tim ist nicht am Sonntag und nicht am Freitag, sondern am Samstag um 10 Uhr. Pastor Schmidt hat den Termin geändert. Die Kirche St. Marien bleibt wie geplant. Danach Essen bei Oma, ab 12 Uhr. Bitte nicht zu spät kommen, sonst ist Tim traurig. Wir sehen uns am Samstag!","gender":"f","q":"Wann ist die Konfirmation?","opts":["Sonntag.","Freitag.","Samstag."],"correct":2},{"transcript":"Hi Markus, hier ist Tom. Ich kann zur Taufe nächste Woche nicht kommen, ich bin auf Dienstreise in Berlin. Ich bin nicht krank, und ich wollte schon lange zur Familie. Sehr schade. Ich komme also nicht zur Taufe, schicke aber ein schönes Geschenk per Post, einen Silberlöffel. Grüße alle und sage sorry von mir!","gender":"m","q":"Was ist mit Tom?","opts":["Er kommt nicht, ist auf Dienstreise.","Er kommt zur Taufe.","Er ist krank."],"correct":0},{"transcript":"Liebe Gäste: Die Hochzeit von Anna und Markus startet pünktlich um 14 Uhr in der Kirche. Bitte 15 Minuten vorher da sein. Es gibt danach ein Buffet, kein Drei-Gänge-Menü und nicht nur Snacks. Es gibt keine festen Plätze, gemütlich und entspannt. Der Geschenke-Tisch steht im Eingang. Wir freuen uns auf alle!","gender":"f","q":"Wie ist das Essen?","opts":["Drei-Gänge-Menü.","Buffet.","Nur Snacks."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Hochzeit deiner Schwester ist schon im Mai."},{"speaker":"Lisa","gender":"f","text":"Ich freue mich sehr. Wir müssen die Aufgaben noch klar verteilen."},{"speaker":"Lukas","gender":"m","text":"Ich mache die Musik als DJ. Bis Mitternacht bleibt es laut im Saal."},{"speaker":"Lisa","gender":"f","text":"Das passt gut zu dir. Ich bringe die Blumen für alle Tische."},{"speaker":"Lukas","gender":"m","text":"Schickt noch jemand die Einladungen per Post?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einladungen brauchen wir nicht. Alle Gäste wissen Bescheid."},{"speaker":"Lukas","gender":"m","text":"Weiß und rosa sehen auf dem Stoff festlich aus."},{"speaker":"Lisa","gender":"f","text":"Tom kommt mit zwei Kameras und macht die Fotos vom ganzen Tag."},{"speaker":"Lukas","gender":"m","text":"In der Küche duftet es seit gestern schon süß."},{"speaker":"Lisa","gender":"f","text":"Sara backt die Torte mit drei Stockwerken. Oben stehen zwei kleine Figuren."},{"speaker":"Lukas","gender":"m","text":"Soll jemand Spiele für die Kinder organisieren?"},{"speaker":"Lisa","gender":"f","text":"Nein. Spiele organisieren wir nicht. Die Kinder tanzen einfach mit."},{"speaker":"Lukas","gender":"m","text":"Tim ist vor dem Essen noch ziemlich nervös."},{"speaker":"Lisa","gender":"f","text":"Tim hält danach die Rede. Er übt die Witze schon im Bad."},{"speaker":"Lukas","gender":"m","text":"Dann sind wir mit dem Plan für den Mai fertig."},{"speaker":"Lisa","gender":"f","text":"Ich schreibe die Liste noch an den Kühlschrank."}],"options":[{"letter":"a","text":"Torte backen"},{"letter":"b","text":"Musik / DJ"},{"letter":"c","text":"Einladungen"},{"letter":"d","text":"Auto schmücken"},{"letter":"e","text":"Blumen"},{"letter":"f","text":"Rede halten"},{"letter":"g","text":"Spiele organisieren"},{"letter":"h","text":"Fotos"},{"letter":"i","text":"Kleidung"}],"items":[{"person":"Lukas","correct":"b"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"h"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Braut","gender":"f","text":"Welche Kleider soll ich wählen? Das weiße klassische oder das cremefarbene?"},{"speaker":"Schwester","gender":"f","text":"Ich finde das weiße klassische besser, es steht dir sehr gut."},{"speaker":"Braut","gender":"f","text":"Oder soll ich keins von beiden nehmen und nächste Woche nochmal suchen?"},{"speaker":"Schwester","gender":"f","text":"Nein, keins weglassen. Beide sind schön, aber das weiße passt besser zur Kirche."},{"speaker":"Braut","gender":"f","text":"Dann nehme ich das weiße. Danke, das hilft mir wirklich!"}],"q":"Welches Kleid wählt sie wahrscheinlich?","opts":["Das weiße.","Das cremefarbene.","Keins."],"correct":0},{"lines":[{"speaker":"Gast","gender":"m","text":"Sag mal, wie viele Gäste kommen denn zur Hochzeit am Samstag?"},{"speaker":"Bräutigam","gender":"m","text":"Wir hatten 100 Leute eingeladen. 85 sagen ja, und 15 haben leider abgesagt."},{"speaker":"Gast","gender":"m","text":"85, das ist ein großes Fest. Reicht das Essen für so viele?"},{"speaker":"Bräutigam","gender":"m","text":"Ja, das Buffet ist für 100 geplant. Genau, alles muss perfekt sein am Samstag."},{"speaker":"Gast","gender":"m","text":"Dann bis Samstag, ich freue mich schon. 85 Gäste, wow!"}],"q":"Wie viele kommen?","opts":["100.","15.","85."],"correct":2},{"lines":[{"speaker":"Mutter","gender":"f","text":"Tochter, was schenken wir Lisa zur Hochzeit? Hast du eine Idee?"},{"speaker":"Tochter","gender":"f","text":"Geld? Oder gar nichts, sie hat schon so viel. Was denkst du?"},{"speaker":"Mutter","gender":"f","text":"Nichts schenken geht nicht. Geld ist ein bisschen unpersönlich. Vielleicht Geschirr?"},{"speaker":"Tochter","gender":"f","text":"Sie hat schon alles an Geschirr. Geld dann doch, in einem netten Briefumschlag."},{"speaker":"Mutter","gender":"f","text":"Okay, dann Geld, nicht Geschirr. Ganz ohne Geschenk geht nicht. Ich hole morgen einen Umschlag."}],"q":"Was schenken sie?","opts":["Geschirr.","Geld.","Nichts."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Wann ist die Trauung morgen? Um 14 Uhr, um 15 Uhr oder später?"},{"speaker":"Sohn","gender":"m","text":"Um 14 Uhr in der Kirche, nicht um 15 Uhr. Bitte sei pünktlich, Papa."},{"speaker":"Vater","gender":"m","text":"Gut, 14 Uhr. Und das Essen danach, wann beginnt das?"},{"speaker":"Sohn","gender":"m","text":"Das Essen ist um 17 Uhr im Hotel Bergblick, nicht gleich nach der Kirche."},{"speaker":"Vater","gender":"m","text":"Alles klar, Trauung 14 Uhr, Essen 17 Uhr. Ich komme rechtzeitig."}],"q":"Wann ist die Trauung?","opts":["15 Uhr.","14 Uhr.","17 Uhr."],"correct":1},{"lines":[{"speaker":"Tante","gender":"f","text":"Wo schlafen wir nach der Feier? Ist das Hotel weit vom Restaurant?"},{"speaker":"Nichte","gender":"f","text":"Ein Hotel haben wir gebucht, das Bergblick. Es ist ganz in der Nähe."},{"speaker":"Tante","gender":"f","text":"Wie weit ist es? 10 Minuten, 5 Minuten oder eine Stunde mit dem Taxi?"},{"speaker":"Nichte","gender":"f","text":"Nur 5 Minuten zu Fuß, nicht 10 Minuten und keine Stunde. Sehr praktisch."},{"speaker":"Tante","gender":"f","text":"Super, 5 Minuten zu Fuß. Dann brauchen wir kein Taxi nach der Feier."}],"q":"Wie weit ist das Hotel?","opts":["5 Minuten.","10 Minuten.","Eine Stunde."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Bachmann, einem Hochzeitsplaner. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Bachmann, Sie planen Hochzeiten seit 12 Jahren. Wie haben Sie damit angefangen?"},{"speaker":"Bachmann","gender":"m","text":"Ein Zufall! Meine Schwester heiratete, alles war chaotisch — niemand organisierte. Ich nahm das in die Hand, alle waren glücklich. Dann fragten Freunde von Freunden. Daraus wurde ein Beruf, eigene Firma, fünf Mitarbeiter heute."},{"speaker":"Reporterin","gender":"f","text":"Was kostet eine Hochzeit durchschnittlich?"},{"speaker":"Bachmann","gender":"m","text":"Sehr unterschiedlich — von 5000 Euro bis 50.000 Euro. Durchschnitt etwa 15.000. Größter Posten ist Location und Essen. Dann Kleid, Fotograf, Musik, Blumen. Hochzeit ist teures Hobby!"},{"speaker":"Reporterin","gender":"f","text":"Welche Trends sehen Sie?"},{"speaker":"Bachmann","gender":"m","text":"Klein und persönlich — statt 200 Gäste oft nur 50, aber alle wichtig. Outdoor-Hochzeiten beliebt, im Wald oder Garten. Themen wie Boho oder Vintage. Klassische große Hochzeit wird weniger."},{"speaker":"Reporterin","gender":"f","text":"Was sind die häufigsten Probleme?"},{"speaker":"Bachmann","gender":"m","text":"Streit zwischen Familien — wer sitzt wo, wer wird eingeladen. Schwiegermütter mischen sich ein. Auch Budget-Überschreitung, fast immer mehr als geplant. Wetter bei Outdoor — Plan B muss da sein."},{"speaker":"Reporterin","gender":"f","text":"Was ist Ihr Rat?"},{"speaker":"Bachmann","gender":"m","text":"Früh planen — 1 Jahr vorher mindestens. Realistisches Budget. Profi-Hilfe nutzen — Hochzeitsplaner spart oft Geld, weil wir die Lieferanten kennen. Aber wichtig: bleibt euch selbst treu, nicht eure Mütter heiraten lassen!"}],"items":[{"q":"Herr Bachmann hat angefangen, weil seine Schwester heiratete.","correct":"ja"},{"q":"Eine Hochzeit kostet immer mindestens 50.000 Euro.","correct":"nein"},{"q":"Outdoor-Hochzeiten sind heute beliebt.","correct":"ja"},{"q":"Wetter ist kein Problem für Outdoor-Hochzeiten.","correct":"nein"},{"q":"Er rät, eine Hochzeit ein Jahr vorher zu planen.","correct":"ja"}]}]};
